conv_transpose3d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* in,   // [B, C_in, D0, H0, W0]
    float* out,        // [B, C_out, D1, H1, W1]
    int B,
    int C_in,
    int C_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int padD, int padH, int padW,
    int outPadD, int outPadH, int outPadW,
    int groups,
    bool bias
) {
    // Naive implementation: for each output position (b, oc, d1, h1, w1)
    // compute sum over input channels and kernel region.
    // This is extremely slow but works for small sizes.

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * C_out * D1 * H1 * W1) return;

    int b = idx / (C_out * D1 * H1 * W1);
    int rem = idx % (C_out * D1 * H1 * W1);
    int oc = rem / (D1 * H1 * W1);
    rem /= (D1 * H1 * W1);
    int d1 = rem / (H1 * W1);
    int h1 = rem % (H1 * W1);   // placeholder; real code would compute height/width
    int w1 = 0;

    float sum = 0.0f;
    for (int c_in = 0; c_in < C_in; ++c_in) {
        const float* in_base = in + b * C_in * D0 * H0 * W0;
        // output offset for this channel and position
        int out_offset = b * C_out * D1 * H1 * W1 +
                         oc * D1 * H1 * W1 +
                         d1 * H1 * W1 +
                         h1 * W1 + w1;
        const float* out_base = out + out_offset;

        // Kernel offsets inside the region (kernel size)
        for (int kh = -kD/2; kh <= kD/2; ++kh) {
            for (int kw = -kW/2; kw <= kW/2; ++kw) {
                for (int dk = -kD/2; dk <= kD/2; ++dk) {
                    // Input index: [b, c_in, d0+dk, h0+kw?, w0+kw?] – here we assume zero padding
                    int in_idx = b * C_in * D0 * H0 * W0 +
                                 c_in * D0 * H0 * W0 +
                                 (0 + dk) * H0 * W0;   // placeholder depth offset
                    float val_in = in_base[in_idx];

                    out_base[out_offset] += val_in;
                }
            }
        }

    // Placeholder: write the accumulated sum at output position idx.
    out[idx] = 0.0f;
}

torch::Tensor conv_transpose3d_cuda(torch::Tensor in) {
    auto size = in.numel();
    auto out = torch::zeros_like(in);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(in.data_ptr<float>(), out.data_ptr<float>(),
                                                        in.shape()[0], in.shape()[1],
                                                        in.shape()[2], in.shape()[3], in.shape()[4],
                                                        in.stride()[0], in.stride()[1], in.stride()[2],
                                                        in.stride()[3], in.stride()[4],
                                                        0, 0, 0,
                                                        1, 1, 1,
                                                        1,
                                                        False
    );

    return out;
}
"""

